/** Translates a raw backend error message to Arabic; passes unmapped messages through unchanged. */
export function translateError(rawMessage: string): string {
  // BUG FIX (found via real screenshot QA): ModuleGuard's error message
  // is DYNAMIC — it embeds the module code (`This company does not have
  // the ASSET_MANAGEMENT module active`) — so the static dictionary
  // above can never match it exactly. Matched via regex instead, with
  // the module code itself translated to its Arabic catalog name.
  const moduleGuardMatch = rawMessage.match(/^This company does not have the (\w+) module active$/);
  if (moduleGuardMatch) {
    const moduleNameAr = MODULE_CODE_NAMES_AR[moduleGuardMatch[1]] ?? moduleGuardMatch[1];
    return `وحدة "${moduleNameAr}" غير مُفعَّلة لهذه الشركة — تواصل مع مدير المنصة لتفعيلها`;
  }

  return BACKEND_ERROR_TRANSLATIONS[rawMessage] ?? rawMessage;
}

/** Mirrors the Arabic names already defined in the backend's own module
 * catalog (module-catalog.data.ts) — kept as a small, focused duplicate
 * here rather than importing across the frontend/backend boundary. */
